[package]
description = "Base Isaac Sim App"
title = "Isaac Sim Base"
version = "6.0.1"
keywords = ["experience", "app", "usd"] # That makes it browsable in UI with "experience" filter


[dependencies]
# Isaac Sim extensions
"isaacsim.app.about" = {}
